UPDATE places SET name_english=place_name,state_name=(SELECT s.state_name FROM cities c JOIN states s ON s.id=c.state_id WHERE c.id=places.city_id),created_at='2026-10-02',updated_at='2026-10-02',verification_status='partial',verification_notes='Identity/source checked; live/provider metadata not fetched.',verified_at='2026-10-02' WHERE id BETWEEN 499000001 AND 499000108;
UPDATE places SET source=CASE city_id WHEN 4990001 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Podgorica / culture / nature pages; checked 2026-10-02' WHEN 4990002 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Cetinje / culture / nature pages; checked 2026-10-02' WHEN 4990003 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Kotor / culture / nature pages; checked 2026-10-02' WHEN 4990004 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Perast / culture / nature pages; checked 2026-10-02' WHEN 4990005 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Budva / culture / nature pages; checked 2026-10-02' WHEN 4990006 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Herceg Novi / culture / nature pages; checked 2026-10-02' WHEN 4990007 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Tivat / culture / nature pages; checked 2026-10-02' WHEN 4990008 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Bar / culture / nature pages; checked 2026-10-02' WHEN 4990009 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Ulcinj / culture / nature pages; checked 2026-10-02' WHEN 4990010 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Žabljak / culture / nature pages; checked 2026-10-02' WHEN 4990011 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Kolašin / culture / nature pages; checked 2026-10-02' WHEN 4990012 THEN 'National Tourism Organisation of Montenegro official travel guide (montenegro.travel), Plužine / culture / nature pages; checked 2026-10-02' END WHERE id BETWEEN 499000001 AND 499000108;
INSERT INTO opening_hours (id,place_id,notes) SELECT id,id,'Exact weekly hours require official/operator/provider refresh; not guessed.' FROM places WHERE id BETWEEN 499000001 AND 499000108;
